import clsx from 'clsx';
import React, {
  forwardRef,
  HTMLAttributes,
  RefObject,
  useLayoutEffect,
  useRef,
} from 'react';
import useResizeObserver from 'use-resize-observer';

import { textEllipsisCSS } from './TextEllipsis.sty.js';
import type { Font } from './utils.js';
import { centerEllipsizeText } from './utils.js';
import { _useFontsUpdated } from '../core/hooks/useFontsUpdated.js';
import { useMergeRefs } from '../core/hooks/useMergeRefs.js';
import type { DataTestId } from '../core/types/data-props.js';
import type { StylingProps } from '../core/types/styling-props.js';

/** Available modes for how overly long text is truncated and where the ellipsis is placed. */
export type TruncationMode = 'start' | 'middle' | 'end';

export interface TextEllipsisProps
  extends HTMLAttributes<HTMLSpanElement>,
    StylingProps,
    DataTestId {
  /** The children (as text) passed to the component. */
  children: string;
  /**
   * The mode used for for truncating the text, either at the start, in the middle or at the end.
   * @defaultValue 'end'
   */
  truncationMode?: TruncationMode;
  /** Gets called when text needs to get truncated due to lack of horizontal space. */
  onTextOverflow?: (ellipsized: boolean) => void;
}

/**
 * Returns an object containing all font-related CSS properties from
 * a given DOM element that are relevant for rendering formatted text
 * in a 2D canvas context.
 *
 * @param textWrapper - The HTML element to extract the CSS properties from
 */
function getFontProps(textWrapper: HTMLSpanElement): Font {
  const computedStyle = window.getComputedStyle(textWrapper, null);

  return {
    fontStyle: computedStyle.getPropertyValue('font-style'),
    fontWeight: computedStyle.getPropertyValue('font-weight'),
    fontSize: computedStyle.getPropertyValue('font-size'),
    fontFamily: computedStyle.getPropertyValue('font-family'),
  };
}

/**
 * Determines whether a CSS text-ellipsis is currently rendered in a container.
 * Note: `containerWidth` is only passed to avoid unnecessary reflows by calling `getBoundingClientRect()`
 */
function isNativeEllipsisActive(
  textWrapper: HTMLSpanElement,
  containerWidth: number,
): boolean {
  const textWidth =
    Math.floor(textWrapper.getBoundingClientRect().width * 100) / 100;

  return textWidth > containerWidth;
}

/**
 * Detects whether a given formatted text has enough space within its
 * parent container and applies or removes an ellipsis accordingly.
 *
 * @param originalText - The text to be truncated if its width exceeds <code>maxWidthInPx</code>
 * @param truncationMode - The mode used for for truncating the text, either at the start, in the middle or at the end
 * @param containerRef - Object ref pointing towards the root element of the TextEllipsis component
 * @param wasEllipsized - Whether an ellipsis was applied during the last render cycle
 * @param onTextOverflow - Callback that gets called whenever the state of the ellipsis changes since the last render cycle
 */
function renderEllipsizedText(
  originalText: string,
  truncationMode: TruncationMode,
  containerRef: RefObject<HTMLSpanElement>,
  wasEllipsized: boolean,
  onTextOverflow?: (ellipsized: boolean) => void,
): boolean {
  const containerElement = containerRef.current;
  const textWrapper: HTMLSpanElement | null =
    (containerElement?.firstElementChild as HTMLSpanElement) || null;

  if (containerElement !== null && textWrapper !== null) {
    if (textWrapper.textContent !== originalText) {
      textWrapper.textContent = originalText; // always reset to full text before measuring container width
    }

    const containerWidth =
      Math.ceil(containerElement.getBoundingClientRect().width * 100) / 100;

    if (truncationMode === 'middle') {
      if (isNativeEllipsisActive(textWrapper, containerWidth)) {
        const ellipsizedText = centerEllipsizeText(
          originalText,
          getFontProps(textWrapper),
          containerWidth,
        );
        textWrapper.textContent = ellipsizedText;

        if (ellipsizedText !== originalText) {
          if (onTextOverflow && !wasEllipsized) {
            onTextOverflow(true);
          }

          return true;
        }
      }

      if (onTextOverflow && wasEllipsized) {
        onTextOverflow(false);
      }
    } else if (isNativeEllipsisActive(textWrapper, containerWidth)) {
      if (onTextOverflow && !wasEllipsized) {
        onTextOverflow(true);
      }

      return true;
    } else if (onTextOverflow && wasEllipsized) {
      onTextOverflow(false);
    }
  }

  return false;
}

const ComputedTextEllipsis = /* @__PURE__ */ forwardRef<
  HTMLSpanElement,
  TextEllipsisProps
>((props, forwardedRef) => {
  const {
    children,
    truncationMode = 'end',
    onTextOverflow,
    className: consumerClassName,
    style: consumerStyle,
    'data-testid': dataTestId,
    ...remainingProps
  } = props;

  // resize observer is needed to re-render the component in case of resizing
  const { ref: observerContainerRef } = useResizeObserver<HTMLSpanElement>();
  const containerRef = useRef<HTMLSpanElement | null>(null);
  const ellipsisStateRef = useRef<boolean>(false);
  const mergedRef = useMergeRefs<HTMLSpanElement | null>([
    observerContainerRef,
    (instance: HTMLSpanElement) => {
      containerRef.current = instance;
    },
    forwardedRef,
  ]);
  const containerWidth = containerRef.current?.getBoundingClientRect().width;
  const fontsUpdated = _useFontsUpdated();

  useLayoutEffect(() => {
    ellipsisStateRef.current = renderEllipsizedText(
      children,
      truncationMode,
      containerRef,
      ellipsisStateRef.current,
      onTextOverflow,
    );
  }, [containerWidth, children, truncationMode, fontsUpdated, onTextOverflow]);

  return (
    <span
      ref={mergedRef}
      aria-label={children}
      data-ellipsis
      data-testid={dataTestId}
      className={clsx(textEllipsisCSS({ truncationMode }), consumerClassName)}
      style={consumerStyle}
      {...remainingProps}
    >
      <span>{children}</span>
    </span>
  );
});

const CssTextEllipsis = /* @__PURE__ */ forwardRef<
  HTMLSpanElement,
  TextEllipsisProps
>((props, forwardedRef) => {
  const {
    children,
    truncationMode = 'end',
    onTextOverflow,
    className: consumerClassName,
    style: consumerStyle,
    'data-testid': dataTestId,
    ...remainingProps
  } = props;

  return (
    <span
      ref={forwardedRef}
      aria-label={children}
      data-ellipsis
      data-testid={dataTestId}
      className={clsx(textEllipsisCSS({ truncationMode }), consumerClassName)}
      style={consumerStyle}
      {...remainingProps}
    >
      <span>{children}</span>
    </span>
  );
});

/**
 * Use the `TextEllipsis` component to truncate text and show an ellipsis whenever
 * there is insufficient space to render the entire text. While some of our Strato
 * components provide ellipsis out of the box, you need to take care of this yourself
 * when writing your own components.
 */
export const TextEllipsis = /* @__PURE__ */ forwardRef<
  HTMLSpanElement,
  TextEllipsisProps
>((props, forwardedRef) => {
  // in case onTextOverflow is not defined and the ellipsis is start or end
  // we can use css only which is significantly more performant
  const cssOnlyEllipsis =
    !props.onTextOverflow && props.truncationMode !== 'middle';

  return cssOnlyEllipsis ? (
    <CssTextEllipsis ref={forwardedRef} {...props} />
  ) : (
    <ComputedTextEllipsis ref={forwardedRef} {...props} />
  );
});

(TextEllipsis as typeof TextEllipsis & { displayName: string }).displayName =
  'TextEllipsis';
